<?php
declare(strict_types=1);
$isHttps=isset($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!==''&&$_SERVER['HTTPS']!=='off';
ini_set('session.use_strict_mode','1');session_name('coaching_tool_session');
session_set_cookie_params(['httponly'=>true,'secure'=>$isHttps,'samesite'=>'Strict','path'=>'/']);session_start();header('Cache-Control: no-store, private');
require_once dirname(__DIR__).'/app/bootstrap.php';
function portalArchiveH(string|int|null $value):string{return htmlspecialchars((string)$value,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
$user=$_SESSION['user']??null;if(!is_array($user)||($user['role']??'')!=='client'||!isset($user['id'],$user['client_id'])){http_response_code(403);exit('Kein Zugriff.');}
$db=coachingDatabase();$clientId=(int)$user['client_id'];$portalId=(int)$user['id'];
$active=$db->prepare('SELECT aktiv FROM coaching_portal_zugaenge WHERE id=:id AND klient_id=:client');$active->execute(['id'=>$portalId,'client'=>$clientId]);if((int)$active->fetchColumn()!==1){http_response_code(403);exit('Der Coachee-Zugang ist nicht aktiv.');}
$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT)?:0;if($id<1){http_response_code(404);exit('Archiv nicht gefunden.');}
$q=$db->prepare("SELECT id,titel,abgeschlossen_am FROM coaching_auftraege WHERE id=:id AND klient_id=:client AND status='abgeschlossen' AND archiv_freigegeben=1");$q->execute(['id'=>$id,'client'=>$clientId]);$order=$q->fetch(PDO::FETCH_ASSOC);if(!$order){http_response_code(404);exit('Archiv nicht gefunden oder nicht freigegeben.');}
$run=function(string $sql,array $params)use($db):array{$q=$db->prepare($sql);$q->execute($params);return $q->fetchAll(PDO::FETCH_ASSOC);};$p=['client'=>$clientId,'order'=>$id];
$appointments=$run('SELECT beginn,dauer_minuten,format,status FROM termine WHERE klient_id=:client AND auftrag_id=:order ORDER BY beginn DESC',$p);
$goals=$run('SELECT titel,beschreibung,erfolgskriterium,zieltermin,status FROM coaching_ziele WHERE klient_id=:client AND auftrag_id=:order ORDER BY geaendert_am DESC',$p);
$tasks=$run('SELECT titel,beschreibung,faellig_am,status FROM coaching_aufgaben WHERE klient_id=:client AND auftrag_id=:order AND klient_sichtbar=1 ORDER BY faellig_am IS NULL,faellig_am',$p);
$messages=$run('SELECT id,autor_rolle,inhalt,erstellt_am FROM coaching_nachrichten WHERE klient_id=:client AND auftrag_id=:order ORDER BY id',$p);$messageFiles=$run('SELECT f.id,f.nachricht_id,f.originalname FROM coaching_nachrichten_dateien f INNER JOIN coaching_nachrichten n ON n.id=f.nachricht_id WHERE f.klient_id=:client AND n.auftrag_id=:order',$p);$mf=[];foreach($messageFiles as $f)$mf[(int)$f['nachricht_id']][]=$f;
$docs=$run("SELECT id,titel,status,zugewiesen_am FROM coaching_klientendokumente WHERE klient_id=:client AND auftrag_id=:order AND status IN ('zugewiesen','ausgegeben','zurueckgekommen') ORDER BY zugewiesen_am DESC",$p);$docFiles=$run("SELECT f.id,f.klientendokument_id,f.version,f.originalname FROM coaching_dokumentdateien f INNER JOIN coaching_klientendokumente d ON d.id=f.klientendokument_id WHERE d.klient_id=:client AND d.auftrag_id=:order AND d.status IN ('zugewiesen','ausgegeben','zurueckgekommen') ORDER BY f.hochgeladen_am DESC",$p);$df=[];foreach($docFiles as $f)$df[(int)$f['klientendokument_id']][]=$f;
?>
<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Coaching-Archiv</title><link rel="stylesheet" href="assets/layout.css"><style>body{background:#f5f7f5}.wrap{max-width:1000px;margin:auto;padding:24px 18px 60px}.card{background:white;border:1px solid #e4ebe6;border-radius:15px;padding:20px;margin:15px 0}.row{border-top:1px solid #edf1ee;padding:12px 0}.muted{color:#718078;font-size:13px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:15px}@media(max-width:700px){.grid{grid-template-columns:1fr}}</style></head><body><main class="wrap"><p><a href="portal.php">← Mein Coaching</a></p><header class="card"><h1><?=portalArchiveH($order['titel'])?></h1><p class="muted">Archivierter Coaching-Auftrag · beendet <?=portalArchiveH($order['abgeschlossen_am']?date('d.m.Y',strtotime($order['abgeschlossen_am'])):'')?></p><p>Dieses Archiv wurde von deinem Coach freigegeben. Private Coach-Notizen sind nicht enthalten.</p></header><div class="grid">
<section class="card"><h2>Sitzungen</h2><?php foreach($appointments as $a):?><div class="row"><strong><?=portalArchiveH(date('d.m.Y · H:i',strtotime($a['beginn'])))?></strong><div class="muted"><?=portalArchiveH($a['format'].' · '.$a['dauer_minuten'].' Min. · '.$a['status'])?></div></div><?php endforeach;?><?php if(!$appointments):?><p class="muted">Keine Sitzungen.</p><?php endif;?></section>
<section class="card"><h2>Ziele</h2><?php foreach($goals as $g):?><div class="row"><strong><?=portalArchiveH($g['titel'])?> · <?=portalArchiveH($g['status'])?></strong><div class="muted"><?=portalArchiveH($g['beschreibung']??'')?><?= $g['zieltermin']?' · Zieltermin '.portalArchiveH(date('d.m.Y',strtotime($g['zieltermin']))):''?></div></div><?php endforeach;?><?php if(!$goals):?><p class="muted">Keine Ziele.</p><?php endif;?></section>
<section class="card"><h2>Aufgaben</h2><?php foreach($tasks as $t):?><div class="row"><strong><?=portalArchiveH($t['titel'])?> · <?=portalArchiveH($t['status'])?></strong><div class="muted"><?=portalArchiveH($t['beschreibung']??'')?></div></div><?php endforeach;?><?php if(!$tasks):?><p class="muted">Keine sichtbaren Aufgaben.</p><?php endif;?></section>
<section class="card"><h2>Nachrichten</h2><?php foreach($messages as $m):?><div class="row"><strong><?= $m['autor_rolle']==='client'?'Du':'Coach' ?> · <?=portalArchiveH(date('d.m.Y H:i',strtotime($m['erstellt_am'])))?></strong><div><?=portalArchiveH($m['inhalt'])?></div><?php foreach($mf[(int)$m['id']]??[] as $f):?><div><a href="message-download.php?id=<?=(int)$f['id']?>"><?=portalArchiveH($f['originalname'])?> herunterladen</a></div><?php endforeach;?></div><?php endforeach;?><?php if(!$messages):?><p class="muted">Keine Nachrichten.</p><?php endif;?></section>
<section class="card"><h2>Dokumente</h2><?php foreach($docs as $d):?><div class="row"><strong><?=portalArchiveH($d['titel'])?> · <?=portalArchiveH($d['status'])?></strong><div><a href="document-download.php?type=assigned-template&amp;id=<?=(int)$d['id']?>">Vorlage öffnen</a></div><?php foreach($df[(int)$d['id']]??[] as $f):?><div class="muted">Rücklauf v<?=(int)$f['version']?> · <a href="document-download.php?type=return&amp;id=<?=(int)$f['id']?>">Öffnen</a></div><?php endforeach;?></div><?php endforeach;?><?php if(!$docs):?><p class="muted">Keine Dokumente.</p><?php endif;?></section></div></main></body></html>